      {required this.clientMessageId,
      required this.groupId,
      required this.body,
      required this.createdAt,
      this.mediaKind,
      this.mediaPath,
      this.mediaThumbPath,
      this.mediaMime,
      this.mediaMeta,
      this.mediaDuration,
      this.mediaSize,
      this.mediaKey,
      this.mediaThumbnailKey,
      this.mediaError,
      required this.failed,
      this.replyToMessageId});
