    return GroupReadsCompanion(
      syncStamp: Value(syncStamp),
      groupId: Value(groupId),
      membershipId: membershipId == null && nullToAbsent
          ? const Value.absent()
          : Value(membershipId),
      lastReadMessageId: lastReadMessageId == null && nullToAbsent
          ? const Value.absent()
